#!/usr/bin/env bash
# Regression test for tests/run_worktree_tests.py: the driver decides what
# code a PR review's test run actually exercises, so its discovery and
# binding contract is pinned here — a test that lives only in the worktree
# must still be found (the case that silently failed with ModuleNotFoundError
# when reviewing PR #1004), and the no-cinbase abort must still bite.
#
# Usage: run from any checkout; designed for the integration branch, where
# the driver exists. An assertion whose precondition is absent skips.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  worktree driver self-test (not inside a git checkout)\n'
    exit 125
}
driver=$root/tests/run_worktree_tests.py
[ -f "$driver" ] || {
    printf 'SKIP  worktree driver self-test (driver absent on this branch)\n'
    exit 125
}

# Bundled interpreter first, then the system one — probed by a real run,
# never by command -v alone (the Store stub answers -v and dies on use).
py=""
for cand in "$root/python/python3/python.exe" "$root/python/python3/python"; do
    if [ -x "$cand" ] && "$cand" -c 'import sys' >/dev/null 2>&1; then
        py=$cand
        break
    fi
done
if [ -z "$py" ] && python3 -c 'import sys' >/dev/null 2>&1; then
    py=python3
fi
[ -n "$py" ] || {
    printf 'SKIP  worktree driver self-test (no working python)\n'
    exit 125
}

# Same WinTEMP rule as check_pr_scope_test.sh: the driver runs under a
# native interpreter that resolves /tmp as C:\tmp, so create and pass one
# Windows-form path both sides agree on.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
tmp=$(mktemp -d "$tmpbase/pime-wt-driver-selftest.XXXXXX") || {
    printf 'FAIL  worktree driver self-test (cannot create temp dir)\n'
    exit 1
}
trap 'rm -rf "$tmp"' EXIT

failures=0

mkdir -p "$tmp/python/cinbase" "$tmp/tests"
printf 'WORKTREE_MARKER = True\n' >"$tmp/python/cinbase/__init__.py"
cat >"$tmp/tests/test_probe.py" <<'EOF'
import unittest

import cinbase


class Probe(unittest.TestCase):
    def test_bound_from_worktree(self):
        self.assertTrue(getattr(cinbase, "WORKTREE_MARKER", False))
EOF

# 1. A test that lives only in the worktree is found, runs, and cinbase
#    binds from the worktree — not from the integration checkout.
out=$("$py" "$driver" "$tmp/tests/test_probe.py" "$tmp" 2>&1) && rc=0 || rc=$?
if [ "$rc" -eq 0 ] && printf '%s\n' "$out" | grep -F "${tmp##*[\\/]}" >/dev/null; then
    printf 'PASS  worktree-local test discovered and bound (exit 0)\n'
else
    printf 'FAIL  worktree-local test: want exit 0 with the probe binding from %s, got exit %s\n%s\n' "$tmp" "$rc" "$out"
    failures=$((failures + 1))
fi

# 2. A worktree carrying no cinbase package aborts with code 3 (the
#    documented invariant: never silently test the wrong tree).
rm -rf "$tmp/python/cinbase"
out=$("$py" "$driver" "$tmp/tests/test_probe.py" "$tmp" 2>&1) && rc=0 || rc=$?
if [ "$rc" -eq 3 ]; then
    printf 'PASS  missing cinbase package aborts (exit 3)\n'
else
    printf 'FAIL  missing cinbase package: want exit 3, got %s\n%s\n' "$rc" "$out"
    failures=$((failures + 1))
fi

if [ "$failures" -ne 0 ]; then
    exit 1
fi
exit 0
